/// Every value of every value table with its DBC label and the signal width.
pub struct EnumVector {
    pub name: &'static str,
    pub bits: u32,
    pub values: &'static [(u8, &'static str)],
}

pub const ENUMS: [EnumVector; 6] = [
    EnumVector { name: "ControllerMode", bits: 4, values: &[(0, "INIT"), (1, "NORMAL"), (2, "DEGRADED"), (3, "SAFE_STATE")] },
    EnumVector { name: "SensorStatus", bits: 4, values: &[(0, "OK"), (1, "DEGRADED"), (2, "FAULT")] },
    EnumVector { name: "NodeState", bits: 4, values: &[(0, "BOOT"), (1, "RUNNING"), (2, "DEGRADED"), (3, "SAFE_STATE"), (4, "FAULT")] },
    EnumVector { name: "CanState", bits: 2, values: &[(0, "ERROR_ACTIVE"), (1, "ERROR_PASSIVE"), (2, "BUS_OFF"), (3, "STOPPED")] },
    EnumVector { name: "Node", bits: 8, values: &[(0, "ALL"), (1, "SENSOR_ECU"), (2, "CONTROLLER_ECU")] },
    EnumVector { name: "TestCommand", bits: 8, values: &[(0, "NOP"), (1, "RESET_FAULTS"), (2, "INJECT_CAN_ERROR"), (3, "FORCE_BUS_OFF"), (4, "SUPPRESS_HEARTBEAT"), (5, "CORRUPT_CRC"), (6, "SKIP_COUNTER"), (7, "FREEZE_COUNTER"), (8, "SUPPRESS_MESSAGE"), (9, "STALL_THREAD")] },
];

/// `name_of` of every generated enum, so the table above can be checked generically.
pub fn enum_name_of(name: &str, raw: u8) -> &'static str {
    match name {
        "ControllerMode" => ControllerMode::name_of(raw),
        "SensorStatus" => SensorStatus::name_of(raw),
        "NodeState" => NodeState::name_of(raw),
        "CanState" => CanState::name_of(raw),
        "Node" => Node::name_of(raw),
        "TestCommand" => TestCommand::name_of(raw),
        _ => "?",
    }
}
